import {DragAndDrop, useDragAndDrop} from '@github-ui/drag-and-drop'
import {getFieldTypeOcticon, type IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {GrabberIcon, KebabHorizontalIcon, PinSlashIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton} from '@primer/react'
import {useRef, useState} from 'react'

import styles from './PinnedIssueFields.module.css'

export type PinnedIssueFieldItemProps = {
  option: IssueField
  onUnpin: (id: string) => void
  index: number
}

export const PinnedIssueFieldItem = ({option, index, onUnpin}: PinnedIssueFieldItemProps) => {
  const editButtonRef = useRef<HTMLButtonElement>(null)
  const [menuOpen, setMenuOpen] = useState(false)
  const {openMoveDialog} = useDragAndDrop()

  const FieldIcon = getFieldTypeOcticon(option.type)

  return (
    <div id={option.id} className={styles.PinnedIssueFieldItem}>
      <DragAndDrop.DragTrigger />
      <div className={styles.PinnedIssueFieldItemContent}>
        {/* eslint-disable-next-line react-hooks/static-components */}
        <FieldIcon className={styles.fieldIcon} />
        <span>{option.name}</span>
      </div>
      <ActionMenu onOpenChange={setMenuOpen} open={menuOpen} anchorRef={editButtonRef}>
        <ActionMenu.Anchor>
          <IconButton
            icon={KebabHorizontalIcon}
            variant="invisible"
            aria-label={`Open field actions for ${option.name}`}
            tooltipDirection="n"
            size="small"
            className={styles.PinnedIssueFieldMenuButton}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            <ActionList.Item
              aria-label={`Advanced move ${option.name}...`}
              onSelect={() => openMoveDialog(option.name, index, editButtonRef)}
            >
              <ActionList.LeadingVisual>
                <GrabberIcon />
                {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
              </ActionList.LeadingVisual>
              Advanced Move...
            </ActionList.Item>
            <ActionList.Item aria-label={`Unpin ${option.name}...`} onSelect={() => onUnpin(option.id)}>
              <ActionList.LeadingVisual>
                <PinSlashIcon />
              </ActionList.LeadingVisual>
              Unpin field
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </div>
  )
}
