import {registerDataRouterApp} from '@github-ui/react-core/register-app'

import {issueTypesSettingsAppBuilder} from './config/app-builder'
import {issueTypesSettingsEditRoute} from './routes/edit-route'
import {EditPage} from './routes/EditPage'
import {issueTypesSettingsIndexRoute} from './routes/index-route'
import {IndexPage} from './routes/IndexPage'
import {issueTypesSettingsNewRoute} from './routes/new-route'
import {NewPage} from './routes/NewPage'

export const issueTypesSettingsApp = issueTypesSettingsAppBuilder.createDataRouterAppFromRoutes([
  issueTypesSettingsIndexRoute.toRoute({Component: IndexPage}),
  issueTypesSettingsNewRoute.toRoute({Component: NewPage}),
  issueTypesSettingsEditRoute.toRoute({Component: EditPage}),
])
registerDataRouterApp(issueTypesSettingsApp)
