import {type DefaultError, useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'

import type {IssueType, IssueTypeColor} from '../types/issue-type'

export type CreateIssueTypeMutationInput = {
  name?: string
  color?: IssueTypeColor | null | undefined
  description?: string | null | undefined
  isEnabled?: boolean
  pinnedIssueFieldIds?: string[]
}

export type CreateIssueTypeMutationResult = IssueType | {errors: string[]}

export function useCreateIssueTypeMutation({
  owner,
  onError,
  onSuccess,
}: {
  owner: string
  onError: (error: Error) => void
  onSuccess: (data: CreateIssueTypeMutationResult) => void
}) {
  return useMutation<CreateIssueTypeMutationResult, DefaultError, CreateIssueTypeMutationInput>({
    onError,
    onSuccess,
    mutationFn: async (payload: CreateIssueTypeMutationInput) => {
      const {name, description, isEnabled, color, pinnedIssueFieldIds} = payload
      const pathname = `/organizations/${owner}/settings/issue-types`

      const formData = new FormData()
      if (name) {
        formData.append('name', name)
      }
      if (description) {
        formData.append('description', description)
      }
      if (isEnabled !== undefined) {
        formData.append('is_enabled', isEnabled.toString())
      }
      if (color) {
        formData.append('color', color)
      }
      if (pinnedIssueFieldIds) {
        formData.append('pinned_issue_field_ids', JSON.stringify(pinnedIssueFieldIds))
      }

      const response = await reactFetch(pathname, {
        method: 'POST',
        body: formData,
      })

      return (await response.json()) as CreateIssueTypeMutationResult
    },
  })
}
